/**
 * The suggestion answers precomputed by this build (scripts/precompute-answers.ts), keyed by the
 * normalised question. They ship in the client bundle, so a bubble click needs no request.
 * The file is generated by the prebuild / predev / preeval:chat steps and is git-ignored.
 */
import data from "./generated/answers.json";
import type { CachedAnswer } from "./answer-cache";

export const PRECOMPUTED: Record<string, CachedAnswer> = (data as unknown as { suggestions: Record<string, CachedAnswer> }).suggestions;
